x.core.ktx)\n implementation(libs.androidx.activity.compose)\n implementation(libs.androidx.lifecycle.runtime.ktx)\n implementation(libs.kotlinx.coroutines.android)\n }\n\n commonMain.dependencies {\n implementation(compose.runtime)\n implementation(compose.foundation)\n implementation(compose.material3)\n implementation(compose.ui)\n implementation(compose.components.resources)\n implementation(libs.kotlinx.coroutines.core)\n implementation(libs.kotlinx.serialization.json)\n }\n\n desktopMain.dependencies {\n implementation(compose.desktop.currentOs)\n }\n }\n}\n\nandroid {\n namespace = \"com.leecoder.multiplatform\"\n compileSdk = 35\n\n defaultConfig {\n applicationId = \"com.leecoder.multiplatform\"\n minSdk = 24\n targetSdk = 35\n versionCode = 1\n versionName = \"1.0\"\n }\n\n packaging {\n resources {\n excludes += \"/META-INF/{AL2.0,LGPL2.1}\"\n }\n }\n\n buildTypes {\n getByName(\"release\") {\n isMinifyEnabled = false\n }\n }\n\n compileOptions {\n sourceCompatibility = JavaVersion.VERSION_17\n targetCompatibility = JavaVersion.VERSION_17\n }\n}\n\ncompose.desktop {\n application {\n mainClass = \"com.leecoder.multiplatform.MainKt\"\n\n nativeDistributions {\n targetFormats(TargetFormat.Dmg, TargetFormat.Msi, TargetFormat.Deb)\n packageName = \"com.leecoder.multiplatform\"\n packageVersion = \"1.0.0\"\n }\n }\n}\n"}"}}]},{"role":"tool","name":"write","tool_call_id":"toolu_01Dt5TgqLkgtApp8X1pHs9uz","content":"Successfully created file at /Users/heesang/AndroidProject/Multiplatform/composeApp/build.gradle.kts
